-- =============================================================================
-- Longblack — Product & Variant Test Seed Data
-- Script: 006-product-variant-test-seed.sql
--
-- Run order: 001-catalogue-schema.sql and 002-catalogue-seed.sql must be run
-- first (this script depends on the existing 'GEN' brand, the 9 leaf
-- categories, and the colours/sizes seeded there).
--
-- Purpose: FOR TESTING ONLY. Creates 3 additional brands, then 30 sample
-- products (spread across every leaf category and across brands) each with
-- 3 variants (90 variants total), so the app has realistic, varied data to
-- browse, filter, and stock-take against.
--
-- Brand distribution:
--   Northfield (NFD)   — menswear   (T-Shirts, Shirts, Jeans, Shorts)
--   Aria (ARA)         — womenswear (Tops, Dresses, Jeans)
--   Urban Thread (UTH) — kidswear   (Boys, Girls)
--   Generic (GEN)      — alternates with the above in every category, so
--                         each category has products from 2 different brands
--
-- How to run against a local PostgreSQL database:
--   psql -U <user> -d <database> -f db/006-product-variant-test-seed.sql
--
-- This script is idempotent: each INSERT uses ON CONFLICT DO NOTHING so rows
-- are only inserted when they do not already exist. It is safe to run multiple
-- times without duplicating data.
--
-- Product code / SKU convention matches the app's suggestion logic:
--   product_code = {brandCode}-{categoryCode}-{sequence}  (sequence is
--     per brand+category pair, see ProductService.SuggestCodeAsync)
--   sku          = {productCode}-{colourCode}-{sizeCode}
--
-- Seed user: rows are attributed to 'system' as the created_by/updated_by value.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Brands (3 additional, alongside the existing 'GEN') — id block 0001
-- ---------------------------------------------------------------------------
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- Products (30) — id block 0005
-- ---------------------------------------------------------------------------
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- Product Variants (90, 3 per product) — id block 0006
-- ---------------------------------------------------------------------------
ON CONFLICT DO NOTHING;
